#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x
WHERE {
  {
    SELECT ?pFrom 
    WHERE {
      ns:m.042f1 ns:government.politician.government_positions_held ?y . # James K. Polk
      ?y ns:government.government_position_held.office_position_or_title ?x ; 
         ns:government.government_position_held.basic_title ns:m.060c4 ; # President
         ns:government.government_position_held.from ?pFrom .
    }
  }
  ns:m.042f1 ns:government.politician.government_positions_held ?y . # James K. Polk
  ?y ns:government.government_position_held.office_position_or_title ?x ; 
     ns:government.government_position_held.from ?from .

  FILTER(xsd:dateTime(?pFrom) - xsd:dateTime(?from) > 0)
}

#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x
WHERE {
  ns:m.04l4rht ns:royalty.noble_title.holders ?y0 .  # Monarch of England
  ?y0 ns:royalty.noble_title_tenure.noble_title ?title ;
      ns:royalty.noble_title_tenure.noble_person ns:m.03p77 ;
      ns:royalty.noble_title_tenure.to_date ?to .

  ns:m.04l4rht ns:royalty.noble_title.holders ?y1 .  # Monarch of England
  ?y1 ns:royalty.noble_title_tenure.noble_person ?x ;
      ns:royalty.noble_title_tenure.from_date ?from .

  FILTER (xsd:datetime(?from) - xsd:datetime(?to) >= 0)
}
ORDER BY xsd:datetime(?from)
LIMIT 1

#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x
WHERE {
{
  SELECT DISTINCT ?f1
  WHERE {
    ns:m.0f2y0 ns:film.film_character.portrayed_in_films ?y .  # Darth Vader
    ?y ns:film.performance.film ?f1 .
    ?f1 ns:film.film.initial_release_date ?d .
  }
  ORDER BY ?d
  LIMIT 1
}
  ns:m.0f2y0 ns:film.film_character.portrayed_in_films ?y .  # Darth Vader
  ?y ns:film.performance.actor ?x ; 
     ns:film.performance.film ?f .
  FILTER (?f1 = ?f)
}
